def solution():
    from pulp import LpProblem, LpVariable, LpMinimize, lpSum, LpStatus
    import numpy as np

    # Define the graph
    graph = {
        1: [3, 7],
        2: [6, 7],
        3: [1, 6],
        6: [2, 3, 8],
        8: [6]
    }

    # Define the vertices and colors
    vertices = list(range(1, 9))
    colors = ['A', 'B', 'C']

    # Create the LP problem
    prob = LpProblem('GraphColoring', LpMinimize)

    # Create the decision variables
    x = {}
    for v in vertices:
        for c in colors:
            x[(v, c)] = LpVariable(f'x_{v}_{c}', cat='Binary')

    # Objective function (minimize the number of colors used)
    prob += lpSum(x[(v, c)] for v in vertices for c in colors)

    # Constraint: Each vertex must be assigned exactly one color
    for v in vertices:
        prob += lpSum(x[(v, c)] for c in colors) == 1

    # Constraint: No two adjacent vertices can have the same color
    for v in vertices:
        for u in graph.get(v, []):
            for c in colors:
                prob += x[(v, c)] + x[(u, c)] <= 1

    # Solve the problem
    prob.solve()

    # Extract the solution
    colors_assignment = {}
    for v in vertices:
        for c in colors:
            if x[(v, c)].value() == 1:
                colors_assignment[v] = c
                break

    return colors_assignment
